use std::thread;
use std::time::Duration;

/// Configuration for retry behaviour.
#[derive(Debug, Clone)]
pub struct RetryConfig {
    pub max_attempts: u32,
    pub initial_delay: Duration,
    pub max_delay: Duration,
    pub multiplier: f64,
}

impl Default for RetryConfig {
    fn default() -> Self {
        Self {
            max_attempts: 3,
            initial_delay: Duration::from_millis(100),
            max_delay: Duration::from_secs(5),
            multiplier: 2.0,
        }
    }
}

/// Errors produced during schema validation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ValidationError {
    TypeMismatch {
        expected: String,
        got: String,
    },
    MissingField(String),
    OutOfRange {
        field: String,
        message: String,
    },
    PatternMismatch {
        field: String,
        pattern: String,
    },
    InvalidSchema(String),
    MaxRetriesExceeded(String),
}

impl std::fmt::Display for ValidationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::TypeMismatch { expected, got } => {
                write!(f, "type mismatch: expected {expected}, got {got}")
            }
            Self::MissingField(name) => write!(f, "missing required field: {name}"),
            Self::OutOfRange { field, message } => {
                write!(f, "field '{field}' out of range: {message}")
            }
            Self::PatternMismatch { field, pattern } => {
                write!(f, "field '{field}' does not match pattern: {pattern}")
            }
            Self::InvalidSchema(msg) => write!(f, "invalid schema: {msg}"),
            Self::MaxRetriesExceeded(msg) => write!(f, "max retries exceeded: {msg}"),
        }
    }
}

impl std::error::Error for ValidationError {}

/// A simplified JSON Schema representation for validation.
#[derive(Debug, Clone)]
pub enum JsonSchema {
    Null,
    Boolean,
    Integer {
        minimum: Option<i64>,
        maximum: Option<i64>,
    },
    Number {
        minimum: Option<f64>,
        maximum: Option<f64>,
    },
    String {
        min_length: Option<usize>,
        max_length: Option<usize>,
        pattern: Option<String>,
    },
    Array {
        items: Option<Box<JsonSchema>>,
        min_items: Option<usize>,
        max_items: Option<usize>,
    },
    Object {
        properties: Vec<(String, JsonSchema)>,
        required: Vec<String>,
    },
    AnyOf(Vec<JsonSchema>),
}

/// A value to be validated — a thin wrapper around common JSON-like types.
#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Integer(i64),
    Number(f64),
    Str(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

/// Validate `value` against `schema`, retrying with exponential backoff when
/// validation returns a transient error.
///
/// The closure `validate_fn` performs the actual validation and returns
/// `Ok(())` on success, `Err(ValidationError)` on failure.  When the error is
/// transient (determined by `is_transient`), the function sleeps with
/// exponential backoff and retries.  Non-transient errors are returned
/// immediately.
///
/// # Examples
/// ```
/// use choucisan::retry_with_backoff::*;
/// use std::time::Duration;
///
/// let schema = JsonSchema::Integer { minimum: Some(0), maximum: Some(100) };
/// let value = Value::Integer(42);
/// let config = RetryConfig::default();
///
/// let result = retry_with_backoff(&value, &schema, &config, validate_value);
/// assert!(result.is_ok());
/// ```
pub fn retry_with_backoff(
    value: &Value,
    schema: &JsonSchema,
    config: &RetryConfig,
    validate_fn: fn(&Value, &JsonSchema) -> Result<(), ValidationError>,
) -> Result<(), ValidationError> {
    let mut delay = config.initial_delay;

    for attempt in 0..config.max_attempts {
        match validate_fn(value, schema) {
            Ok(()) => return Ok(()),
            Err(e) => {
                if attempt + 1 >= config.max_attempts {
                    return Err(ValidationError::MaxRetriesExceeded(e.to_string()));
                }

                // Only retry transient errors (schema-level issues that might
                // resolve on a subsequent attempt, e.g. a remote schema ref
                // that is temporarily unavailable).
                if !is_transient(&e) {
                    return Err(e);
                }

                thread::sleep(delay);
                delay = Duration::from_secs_f64(
                    (delay.as_secs_f64() * config.multiplier).min(config.max_delay.as_secs_f64()),
                );
            }
        }
    }

    Err(ValidationError::MaxRetriesExceeded(
        "exhausted all attempts".to_string(),
    ))
}

/// Determine whether an error is transient and worth retrying.
fn is_transient(err: &ValidationError) -> bool {
    matches!(err, ValidationError::InvalidSchema(_))
}

/// Validate a `Value` against a `JsonSchema`.
pub fn validate_value(value: &Value, schema: &JsonSchema) -> Result<(), ValidationError> {
    match schema {
        JsonSchema::Null => match value {
            Value::Null => Ok(()),
            _ => Err(ValidationError::TypeMismatch {
                expected: "null".to_string(),
                got: type_name(value),
            }),
        },

        JsonSchema::Boolean => match value {
            Value::Bool(_) => Ok(()),
            _ => Err(ValidationError::TypeMismatch {
                expected: "boolean".to_string(),
                got: type_name(value),
            }),
        },

        JsonSchema::Integer { minimum, maximum } => match value {
            Value::Integer(n) => {
                if let Some(min) = minimum {
                    if *n < *min {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("{n} < minimum {min}"),
                        });
                    }
                }
                if let Some(max) = maximum {
                    if *n > *max {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("{n} > maximum {max}"),
                        });
                    }
                }
                Ok(())
            }
            _ => Err(ValidationError::TypeMismatch {
                expected: "integer".to_string(),
                got: type_name(value),
            }),
        },

        JsonSchema::Number { minimum, maximum } => match value {
            Value::Number(n) => {
                if let Some(min) = minimum {
                    if *n < *min {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("{n} < minimum {min}"),
                        });
                    }
                }
                if let Some(max) = maximum {
                    if *n > *max {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("{n} > maximum {max}"),
                        });
                    }
                }
                Ok(())
            }
            Value::Integer(n) => {
                let n_f = *n as f64;
                if let Some(min) = minimum {
                    if n_f < *min {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("{n_f} < minimum {min}"),
                        });
                    }
                }
                if let Some(max) = maximum {
                    if n_f > *max {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("{n_f} > maximum {max}"),
                        });
                    }
                }
                Ok(())
            }
            _ => Err(ValidationError::TypeMismatch {
                expected: "number".to_string(),
                got: type_name(value),
            }),
        },

        JsonSchema::String {
            min_length,
            max_length,
            pattern,
        } => match value {
            Value::Str(s) => {
                if let Some(min) = min_length {
                    if s.len() < *min {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("length {} < minLength {min}", s.len()),
                        });
                    }
                }
                if let Some(max) = max_length {
                    if s.len() > *max {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("length {} > maxLength {max}", s.len()),
                        });
                    }
                }
                if let Some(pat) = pattern {
                    if !simple_pattern_match(pat, s) {
                        return Err(ValidationError::PatternMismatch {
                            field: "value".to_string(),
                            pattern: pat.clone(),
                        });
                    }
                }
                Ok(())
            }
            _ => Err(ValidationError::TypeMismatch {
                expected: "string".to_string(),
                got: type_name(value),
            }),
        },

        JsonSchema::Array {
            items,
            min_items,
            max_items,
        } => match value {
            Value::Array(arr) => {
                if let Some(min) = min_items {
                    if arr.len() < *min {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("length {} < minItems {min}", arr.len()),
                        });
                    }
                }
                if let Some(max) = max_items {
                    if arr.len() > *max {
                        return Err(ValidationError::OutOfRange {
                            field: "value".to_string(),
                            message: format!("length {} > maxItems {max}", arr.len()),
                        });
                    }
                }
                if let Some(item_schema) = items {
                    for (i, item) in arr.iter().enumerate() {
                        validate_value(item, item_schema).map_err(|e| match e {
                            ValidationError::TypeMismatch { expected, got } => {
                                ValidationError::TypeMismatch {
                                    expected: format!("items[{i}]: {expected}"),
                                    got,
                                }
                            }
                            other => other,
                        })?;
                    }
                }
                Ok(())
            }
            _ => Err(ValidationError::TypeMismatch {
                expected: "array".to_string(),
                got: type_name(value),
            }),
        },

        JsonSchema::Object {
            properties,
            required,
        } => match value {
            Value::Object(map) => {
                // Check required fields.
                for req in required {
                    if !map.iter().any(|(k, _)| k == req) {
                        return Err(ValidationError::MissingField(req.clone()));
                    }
                }
                // Validate each present property against its schema.
                for (key, val) in map {
                    if let Some((_, prop_schema)) = properties.iter().find(|(k, _)| k == key) {
                        validate_value(val, prop_schema)?;
                    }
                }
                Ok(())
            }
            _ => Err(ValidationError::TypeMismatch {
                expected: "object".to_string(),
                got: type_name(value),
            }),
        },

        JsonSchema::AnyOf(schemas) => {
            for schema in schemas {
                if validate_value(value, schema).is_ok() {
                    return Ok(());
                }
            }
            Err(ValidationError::TypeMismatch {
                expected: "anyOf match".to_string(),
                got: type_name(value),
            })
        }
    }
}

fn type_name(v: &Value) -> String {
    match v {
        Value::Null => "null".to_string(),
        Value::Bool(_) => "boolean".to_string(),
        Value::Integer(_) => "integer".to_string(),
        Value::Number(_) => "number".to_string(),
        Value::Str(_) => "string".to_string(),
        Value::Array(_) => "array".to_string(),
        Value::Object(_) => "object".to_string(),
    }
}

/// Very simple pattern matching: supports `^...$` anchored literal patterns
/// and `.*` / `.+` wildcards.  Not a full regex engine — just enough for
/// basic schema validation.
fn simple_pattern_match(pattern: &str, input: &str) -> bool {
    let p = pattern;

    // Exact match (anchored literal).
    if p.starts_with('^') && p.ends_with('$') {
        let inner = &p[1..p.len() - 1];
        if inner == ".*" {
            return true;
        }
        if inner == ".+" {
            return !input.is_empty();
        }
        // Treat as literal prefix/suffix.
        if let Some(idx) = inner.find(".*") {
            let prefix = &inner[..idx];
            let suffix = &inner[idx + 2..];
            return input.starts_with(prefix) && input.ends_with(suffix);
        }
        return input == inner;
    }

    // Unanchored: check if the pattern appears as a substring.
    input.contains(p)
}

