        assert!(!result.unwrap_err().to_string().contains("max retries"));
    }

    #[test]
    fn retry_exhausts_attempts_on_transient_error() {
        // An always-failing transient validator.
        fn always_invalid_schema(_: &Value, _: &JsonSchema) -> Result<(), ValidationError> {
            Err(ValidationError::InvalidSchema("remote schema unavailable".into()))
        }

        let schema = JsonSchema::Null;
        let config = RetryConfig {
            max_attempts: 3,
            initial_delay: Duration::from_millis(1),
            max_delay: Duration::from_millis(5),
            multiplier: 2.0,
        };
        let result = retry_with_backoff(&Value::Null, &schema, &config, always_invalid_schema);
        assert!(result.is_err());
        assert!(result.unwrap_err().to_string().contains("max retries"));
    }

    #[test]
    fn retry_succeeds_after_transient_failures() {
        use std::sync::atomic::{AtomicU32, Ordering};

        static ATTEMPTS: AtomicU32 = AtomicU32::new(0);

        fn flaky_validate(value: &Value, schema: &JsonSchema) -> Result<(), ValidationError> {
            let attempt = ATTEMPTS.fetch_add(1, Ordering::SeqCst);
            if attempt < 2 {
                return Err(ValidationError::InvalidSchema("transient failure".into()));
            }
            validate_value(value, schema)
        }

        ATTEMPTS.store(0, Ordering::SeqCst);

        let schema = JsonSchema::Integer {
            minimum: None,
            maximum: None,
        };
        let config = RetryConfig {
            max_attempts: 5,
            initial_delay: Duration::from_millis(1),
            max_delay: Duration::from_millis(10),
            multiplier: 2.0,
        };
        let result = retry_with_backoff(&Value::Integer(42), &schema, &config, flaky_validate);
        assert!(result.is_ok());
        assert!(ATTEMPTS.load(Ordering::SeqCst) >= 3);
    }

